mapper.select:
select *
from iot_device_log


    and iot_id = #{iotId}


    and message_type = #{messageType}


    and create_time >= to_timestamp(#{params.beginCreateTime})


    and create_time <= to_timestamp(#{params.endCreateTime})


    and product_key = #{productKey}


    and device_id = #{deviceId}


    and device_name like concat('%', #{deviceName}, '%')


    and COALESCE(NULLIF(content, ''), '{}')::jsonb ->> 'event' = #{params.event}


    and jsonb_exists(COALESCE(NULLIF(content, ''), '{}')::jsonb -> 'properties', #{params.properties})


order by create_time desc

select *
from iot_device_log


    and id = CAST(#{id} AS bigint)


    and iot_id = #{iotId}


    and product_key = #{productKey}

select *
from iot_device_log


    and iot_id = #{iotId}


    and message_type = #{messageType}


    and create_time >= to_timestamp(#{params.beginCreateTime})


    and create_time <= to_timestamp(#{params.endCreateTime})


    and product_key = #{productKey}


    and device_id = #{deviceId}


    and device_name like concat('%', #{deviceName}, '%')


    and COALESCE(NULLIF(content, ''), '{}')::jsonb ->> 'event' = #{params.event}


    and jsonb_exists(COALESCE(NULLIF(content, ''), '{}')::jsonb -> 'properties', #{params.properties})


order by create_time desc

SELECT COUNT(*) AS totalCount,
       MAX(create_time) AS latestCreateTime
FROM iot_device_log
WHERE iot_id = #{iotId}
  AND message_type = 'EVENT'
  AND event = #{event}
